from common7 import *
def main():
 m,o=metadata();daily=np.load(PRIVATE/'daily_features.npy');u=m['cluster'];y=m['y'];cal=o['calendar'];dates=o['rowdate'];di=(dates-cal[0]).astype(int);users=o['user'];op=read(OUT/'OPERATIONAL_RESULTS.json');timing=op['timing'];trace=[r for r in timing if r['model']=='TRACE'];cases=sorted({r['user'] for r in trace if not r['detected']});allmissed=[a for a in cases if all(not r['detected'] for r in trace if r['user']==a)];assert cases
 selection=read(EXPL/'HOLDOUT_SELECTION.json');take=np.array(selection['selected_bundle_row_indices']);rev={int(j):i for i,j in enumerate(take)};assert set(np.flatnonzero(y))<=set(take)
 features=[];windows=[];peaks=[];overall=[];attrows=[];igrows=[];treerows=[];case_summary=[];attributions=[];activity=[];coverage=[];missing=[];diagnostics=[]
 for user in cases:
  ui=int(np.flatnonzero(users==user)[0]);mal=np.flatnonzero(o['daily_y'][ui]);normal=daily[ui,o['daily_y'][ui]==0];med=np.median(normal,axis=0);rows=np.flatnonzero((u==ui)&(y==1));scenario=next(r['scenario'] for r in trace if r['user']==user)
  for day in mal:
   for j,f in enumerate(FEATURES):features.append(dict(user=user,scenario=scenario,date=str(cal[day]),feature=f,malicious_day_value=float(daily[ui,day,j]),own_nonmalicious_day_median=float(med[j]),difference=float(daily[ui,day,j]-med[j]),nonmalicious_reference_days=len(normal)))
  case_summary.append(dict(user=user,scenario=scenario,malicious_days=len(mal),first_malicious_day=str(cal[mal[0]]),last_malicious_day=str(cal[mal[-1]]),span_calendar_days=int(mal[-1]-mal[0]+1),malicious_window_count=len(rows),nonmalicious_reference_days=len(normal),nonmalicious_active_days=int((normal[:,12]>0).sum()),nonmalicious_inactive_days=int((normal[:,12]==0).sum()),missed_all_TRACE_seeds=user in allmissed,missed_TRACE_seeds=[r['seed'] for r in trace if r['user']==user and not r['detected']]))
  for s in SEEDS:
   p=score('TRACE',s);t=spec('TRACE',s)['threshold'];ranks=np.load(PRIVATE/f'ranks/TRACE_{s}.npy');best=int(rows[np.lexsort((rows,dates[rows],-p[rows]))[0]]);ci=rev.get(best);allrows=np.flatnonzero(u==ui);high=int(allrows[np.lexsort((allrows,dates[allrows],-p[allrows]))[0]])
   overall.append(dict(user=user,seed=s,source_row=high,end_date=str(dates[high]),max_all_window_score=float(p[high]),threshold=t,global_window_rank=float(ranks[high]),contains_malicious_day=bool(y[high]),alert=bool(p[high]>=t),days_since_last_malicious_day=int((dates[high]-cal[mal[-1]]).astype(int)),all_alert_windows=int((p[allrows]>=t).sum()),malicious_alert_windows=int((p[rows]>=t).sum())))
   for j in np.flatnonzero(u==ui):windows.append(dict(user=user,scenario=scenario,seed=s,source_row=int(j),start_date=str(dates[j]-np.timedelta64(19,'D')),end_date=str(dates[j]),partition=str(m['partition'][j]),contains_malicious_day=bool(y[j]),malicious_endpoint=bool(m['endpoint'][j]),score=float(p[j]),threshold=t,alert=bool(p[j]>=t),global_window_rank=float(ranks[j])))
   peaks.append(dict(user=user,scenario=scenario,seed=s,source_row=best,end_date=str(dates[best]),max_malicious_window_score=float(p[best]),threshold=t,score_margin=float(p[best]-t),global_window_rank=float(ranks[best]),rank_percent=float(ranks[best]/len(y)*100),malicious_days_within_window=int(o['daily_y'][ui,di[best]-19:di[best]+1].sum()),detected=bool((p[rows]>=t).any())))
   if ci is None:missing.append(dict(user=user,seed=s,component='all explanations',reason='highest-scoring malicious window absent from saved cohort'));continue
   inter=np.load(B6P/f'explanation/seed{s}/cohort_intermediates.npz');iz=np.load(EXPL/f'ig_seed{s}.npz');ig=iz['ig'][ci,-1].astype(float);assert int(inter['source_row'][ci])==best;attention=inter['attention'][ci];assert abs(attention.sum()-1)<1e-5
   diagnostics.append(dict(user=user,seed=s,source_row=best,original_logit=float(inter['original_logit'][ci]),threshold_logit=float(np.log(t/(1-t))),attention_mass_on_malicious_days=float(attention[o['daily_y'][ui,di[best]-19:di[best]+1]==1].sum()),malicious_day_fraction=float(o['daily_y'][ui,di[best]-19:di[best]+1].mean()),IG_logit_difference=float(iz['differences'][ci,-1]),IG_completeness_residual=float(iz['residual'][ci,-1]),IG_relative_completeness_residual=float(iz['relative'][ci,-1])))
   absfeature=np.abs(ig).sum(0);total=absfeature.sum();order=np.argsort(-absfeature,kind='stable')
   for j,f in enumerate(FEATURES):igrows.append(dict(user=user,seed=s,source_row=best,feature=f,signed_IG_sum=float(ig[:,j].sum()),absolute_IG=float(absfeature[j]),absolute_IG_share=float(absfeature[j]/total) if total else None,absolute_rank=int(np.flatnonzero(order==j)[0]+1)))
   for k,a in enumerate(attention):attrows.append(dict(user=user,seed=s,source_row=best,timestep=k+1,date=str(dates[best]-np.timedelta64(19-k,'D')),attention=float(a),malicious_day=int(o['daily_y'][ui,di[best]-19+k]),IG_absolute_share=float(np.abs(ig[k]).sum()/total) if total else None))
   refs=read(B6P/f'explanation/seed{s}/TRAIN_TREE_REFERENCES.json');tr=inter['tree'][ci];center=(tr-np.array(refs['tree_output_mean']))/8.;order=np.argsort(-np.abs(center),kind='stable')
   for j in range(8):treerows.append(dict(user=user,seed=s,source_row=best,tree=j+1,raw_tree_output=float(tr[j]),development_TRAIN_reference=float(refs['tree_output_mean'][j]),reference_centred_logit_contribution=float(center[j]),absolute_rank=int(np.flatnonzero(order==j)[0]+1),top_three=bool(j in order[:3])))
 # P2 full-window activity summaries, with explicit overlap weighting and unique-day alternative.
 for s in SEEDS:
  p=score('TRACE',s);flag=p>=spec('TRACE',s)['threshold'];iz=np.load(EXPL/f'ig_seed{s}.npz');ig=iz['ig'][:,-1].astype(float);ab=np.abs(ig);den=ab.sum((1,2));shares=np.divide(ab.sum(1),den[:,None],out=np.full((len(take),13),np.nan),where=den[:,None]>0)
  for group,mask in [('false_alarm_noninsider',flag&(~o['insider'][u])),('true_positive',flag&(y==1))]:
   ix=np.flatnonzero(mask);selected=np.flatnonzero(mask[take]);valid=selected[den[selected]>0];rel=iz['relative'][valid,-1];coverage.append(dict(seed=s,group=group,full_windows=len(ix),saved_explanation_windows=len(selected),valid_IG_windows=len(valid),zero_total_IG_excluded=len(selected)-len(valid),coverage_fraction=len(selected)/len(ix) if len(ix) else None,median_IG_relative_completeness_residual=float(np.median(rel)) if len(rel) else None,P95_IG_relative_completeness_residual=float(np.quantile(rel,.95)) if len(rel) else None))
   for j,f in enumerate(FEATURES):attributions.append(dict(seed=s,group=group,level='feature',name=f,mean_absolute_IG_share=float(np.mean(shares[valid,j])) if len(valid) else None,explanation_windows=len(valid)))
   for source,cols in SOURCE_GROUPS.items():attributions.append(dict(seed=s,group=group,level='source',name=source,mean_absolute_IG_share=float(np.mean(shares[valid][:,cols].sum(1))) if len(valid) else None,explanation_windows=len(valid)))
   cells=(u[ix,None].astype(np.int64)*464+di[ix,None]-19+np.arange(20)).ravel();assert not len(cells) or (cells.min()>=0 and cells.max()<500*464);weights=np.bincount(cells,minlength=500*464);assert weights.sum()==len(ix)*20;a=daily.reshape(-1,13);means=weights@a/weights.sum() if weights.sum() else np.full(13,np.nan);unique=a[weights>0].mean(0) if (weights>0).any() else np.full(13,np.nan)
   for j,f in enumerate(FEATURES):activity.append(dict(seed=s,group=group,feature=f,window_day_weighted_mean=float(means[j]),unique_user_day_mean=float(unique[j]),windows=len(ix),window_day_instances=len(cells),unique_user_days=int((weights>0).sum())))
 cross=[r for r in timing if r['user'] in cases and r['model']!='TRACE']
 for name,rows in [('P1_CASE_SUMMARY.csv',case_summary),('P1_MALICIOUS_DAY_FEATURES.csv',features),('P1_ALL_CASE_WINDOW_SCORES.csv',windows),('P1_MALICIOUS_CONTAINING_WINDOW_SCORES.csv',[r for r in windows if r['contains_malicious_day']]),('P1_PEAK_MALICIOUS_WINDOW.csv',peaks),('P1_PEAK_ALL_WINDOWS.csv',overall),('P1_OTHER_MODEL_DETECTION.csv',cross),('P1_PEAK_ATTENTION_20_DAYS.csv',attrows),('P1_PEAK_IG_FEATURES.csv',igrows),('P1_PEAK_TREE_CONTRIBUTIONS.csv',treerows),('P1_EXPLANATION_DIAGNOSTICS.csv',diagnostics),('P2_IG_COVERAGE.csv',coverage),('P2_IG_SHARES.csv',attributions),('P2_DAILY_ACTIVITY_FEATURES.csv',activity)]:csv(name,rows)
 dump(OUT/'CASE_ATTRIBUTION_RESULTS.json',dict(utc=utc(),cases=case_summary,all_seeds_missed=allmissed,peak_windows=peaks,peak_all_windows=overall,other_model_detection=cross,malicious_day_features=features,attention=attrows,IG_features=igrows,tree_contributions=treerows,explanation_diagnostics=diagnostics,P2_coverage=coverage,P2_attribution=attributions,P2_activity=activity,missing_components=missing,new_IG_or_interventions=False,new_holdout_inference=False));status('CASE_ATTRIBUTION_COMPLETE',cases=len(cases),missed_all_seeds=len(allmissed),missing_components=len(missing))
